-- ============================================================================
-- DO NOT EDIT THIS FILE ONCE IT HAS BEEN APPLIED TO ANY DATABASE.
-- Until then it may still change. After it is applied, every change goes in a
-- new migration file with a later timestamp.
-- ============================================================================
--
-- AI Auto Chat settings: the master switch, persona, handover rules, pipeline
-- trigger rules and knowledge sources the auto chat will read once OpenAI and
-- WhatsApp are connected. Nothing in the app reads these settings to answer
-- customers yet; this only stores them.
--
-- Also adds the Developer role. A Developer manages every setting an Admin
-- can, but public.is_admin() is NOT widened: a Developer sees no leads, sales
-- users or chats unless that function is changed in a later migration.
--
-- Changes to existing objects (both widen, nothing is dropped or rewritten):
--   1. sales_users_role_check is replaced by the same check plus 'Developer'.
--      No row changes; every current role stays valid.
-- Everything else is new: one private function, three tables, one private
-- storage bucket and their policies, plus seed rows in the new tables only.
--
-- Depends on 20261112090000_whatsapp.sql (private.set_updated_at,
-- private.current_sales_user_id).
-- Applied to crm-fsi on 2026-11-24 after the owner approved the SQL.

-- 1. Developer role -----------------------------------------------------------

alter table public.sales_users
    drop constraint sales_users_role_check,
    add constraint sales_users_role_check
        check (role = any (array['Admin', 'Sales', 'Digital Marketing', 'Secretary', 'Developer']));

-- Admin or Developer, and not marked Inactive. Security definer so policies can
-- read sales_users without the caller's own sales_users policies applying.
create function private.can_manage_settings()
returns boolean
language sql
stable
security definer
set search_path = ''
as $$
    select exists (
        select 1
        from public.sales_users su
        where su."auth_user-id" = (select auth.uid())
          and su.role = any (array['Admin', 'Developer'])
          and su.status is distinct from 'Inactive'
    );
$$;

revoke execute on function private.can_manage_settings() from public, anon;
grant execute on function private.can_manage_settings() to authenticated;

-- 2. Settings (one row) -------------------------------------------------------

create table public.ai_chat_settings (
    id smallint primary key default 1,
    enabled boolean not null default false,
    -- OpenAI only. The API key is a server environment variable, never stored here.
    provider text not null default 'openai',
    model text,
    persona_name text not null default 'FSI Assistant',
    tone text not null default 'professional',
    tone_custom text,
    language_mode text not null default 'auto',
    greeting_en text,
    greeting_id text,
    rules text,
    handover_keywords text[] not null default '{}',
    handover_max_failed_answers smallint not null default 2,
    handover_on_human_request boolean not null default true,
    handover_message_en text,
    handover_message_id text,
    updated_by uuid references public.sales_users (id) on delete set null,
    updated_at timestamptz not null default now(),
    constraint ai_chat_settings_single_row check (id = 1),
    constraint ai_chat_settings_provider_check check (provider = 'openai'),
    constraint ai_chat_settings_tone_check
        check (tone = any (array['professional', 'natural', 'friendly', 'custom'])),
    constraint ai_chat_settings_tone_custom_check
        check (tone <> 'custom' or length(trim(coalesce(tone_custom, ''))) > 0),
    constraint ai_chat_settings_language_check
        check (language_mode = any (array['auto', 'en', 'id'])),
    constraint ai_chat_settings_failed_answers_check
        check (handover_max_failed_answers between 1 and 10)
);

-- 3. Pipeline trigger rules ---------------------------------------------------

create table public.ai_chat_trigger_rules (
    id uuid primary key default gen_random_uuid(),
    name text not null,
    -- What the customer says or does in the chat; becomes an instruction to the AI.
    trigger_description text not null,
    -- A value stored in leads.status today.
    target_status text not null,
    enabled boolean not null default true,
    -- v1 only suggests a move and a salesperson confirms it. Stored for later.
    auto_move boolean not null default false,
    sort_order integer not null default 0,
    created_by uuid references public.sales_users (id) on delete set null,
    updated_by uuid references public.sales_users (id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint ai_chat_trigger_rules_name_check check (length(trim(name)) between 1 and 120),
    constraint ai_chat_trigger_rules_trigger_check
        check (length(trim(trigger_description)) between 1 and 2000),
    constraint ai_chat_trigger_rules_status_check
        check (target_status = any (array[
            'New',
            'First Contact',
            'First Meeting / Appointment / Site Survey',
            'Quotation',
            'Second Appointment',
            'Deal',
            'No Deal'
        ]))
);

create index ai_chat_trigger_rules_sort_idx on public.ai_chat_trigger_rules (sort_order, created_at);

-- 4. Knowledge sources --------------------------------------------------------

create table public.ai_knowledge_sources (
    id uuid primary key default gen_random_uuid(),
    kind text not null,
    title text not null,
    -- kind = 'note': the text itself.
    body text,
    -- kind = 'file': the object in the ai-knowledge bucket.
    file_path text unique,
    file_name text,
    mime_type text,
    file_size bigint,
    -- Indexing starts once OpenAI is connected; until then every source waits.
    status text not null default 'pending_index',
    status_detail text,
    created_by uuid references public.sales_users (id) on delete set null,
    created_at timestamptz not null default now(),
    updated_at timestamptz not null default now(),
    constraint ai_knowledge_sources_kind_check check (kind = any (array['file', 'note'])),
    constraint ai_knowledge_sources_status_check
        check (status = any (array['pending_index', 'indexing', 'indexed', 'failed'])),
    constraint ai_knowledge_sources_title_check check (length(trim(title)) between 1 and 200),
    constraint ai_knowledge_sources_shape_check check (
        (kind = 'file' and file_path is not null and body is null)
        or (kind = 'note' and file_path is null and length(trim(coalesce(body, ''))) > 0)
    )
);

create index ai_knowledge_sources_created_idx on public.ai_knowledge_sources (created_at desc);

-- 5. updated_at ---------------------------------------------------------------

create trigger ai_chat_settings_set_updated_at
    before update on public.ai_chat_settings
    for each row execute function private.set_updated_at();

create trigger ai_chat_trigger_rules_set_updated_at
    before update on public.ai_chat_trigger_rules
    for each row execute function private.set_updated_at();

create trigger ai_knowledge_sources_set_updated_at
    before update on public.ai_knowledge_sources
    for each row execute function private.set_updated_at();

-- 6. RLS: Admin and Developer only --------------------------------------------

alter table public.ai_chat_settings enable row level security;
alter table public.ai_chat_trigger_rules enable row level security;
alter table public.ai_knowledge_sources enable row level security;

revoke all on public.ai_chat_settings, public.ai_chat_trigger_rules, public.ai_knowledge_sources from anon;

-- The single settings row is seeded below; it can be read and updated, never added or removed.
create policy ai_chat_settings_select on public.ai_chat_settings
    for select to authenticated
    using ((select private.can_manage_settings()));

create policy ai_chat_settings_update on public.ai_chat_settings
    for update to authenticated
    using ((select private.can_manage_settings()))
    with check ((select private.can_manage_settings()));

create policy ai_chat_trigger_rules_select on public.ai_chat_trigger_rules
    for select to authenticated
    using ((select private.can_manage_settings()));

create policy ai_chat_trigger_rules_insert on public.ai_chat_trigger_rules
    for insert to authenticated
    with check ((select private.can_manage_settings()));

create policy ai_chat_trigger_rules_update on public.ai_chat_trigger_rules
    for update to authenticated
    using ((select private.can_manage_settings()))
    with check ((select private.can_manage_settings()));

create policy ai_chat_trigger_rules_delete on public.ai_chat_trigger_rules
    for delete to authenticated
    using ((select private.can_manage_settings()));

create policy ai_knowledge_sources_select on public.ai_knowledge_sources
    for select to authenticated
    using ((select private.can_manage_settings()));

create policy ai_knowledge_sources_insert on public.ai_knowledge_sources
    for insert to authenticated
    with check ((select private.can_manage_settings()));

create policy ai_knowledge_sources_update on public.ai_knowledge_sources
    for update to authenticated
    using ((select private.can_manage_settings()))
    with check ((select private.can_manage_settings()));

create policy ai_knowledge_sources_delete on public.ai_knowledge_sources
    for delete to authenticated
    using ((select private.can_manage_settings()));

-- 7. Storage bucket -----------------------------------------------------------

-- Private, 20 MB per file: PDF, Word (.docx), images and plain text.
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values (
    'ai-knowledge',
    'ai-knowledge',
    false,
    20971520,
    array[
        'application/pdf',
        'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
        'image/png',
        'image/jpeg',
        'image/webp',
        'text/plain'
    ]
);

create policy ai_knowledge_storage_select on storage.objects
    for select to authenticated
    using (bucket_id = 'ai-knowledge' and (select private.can_manage_settings()));

create policy ai_knowledge_storage_insert on storage.objects
    for insert to authenticated
    with check (bucket_id = 'ai-knowledge' and (select private.can_manage_settings()));

create policy ai_knowledge_storage_delete on storage.objects
    for delete to authenticated
    using (bucket_id = 'ai-knowledge' and (select private.can_manage_settings()));

